insert into public.concept_relationships(source_concept_id,target_concept_id,relation_type,explanation,validation_status)
select a.id,b.id,p.kind,p.explanation,'proposed' from proposed p join public.knowledge_concepts a on a.slug=p.a join public.knowledge_concepts b on b.slug=p.b
on conflict(source_concept_id,target_concept_id,relation_type) do nothing;
insert into public.knowledge_edges(source_node_id,target_node_id,relation_type,weight,metadata)
select sa.id,ta.id,cr.relation_type,case when cr.relation_type='prerequisite_for' then 0.8 else 0.5 end,jsonb_build_object('validation_status',cr.validation_status,'explanation',cr.explanation)
from public.concept_relationships cr join public.knowledge_nodes sa on sa.entity_type='concept' and sa.entity_id=cr.source_concept_id
join public.knowledge_nodes ta on ta.entity_type='concept' and ta.entity_id=cr.target_concept_id
on conflict(source_node_id,target_node_id,relation_type) do nothing;